import React, { useState } from 'react';

type Page = 'login' | 'booking' | 'payment' | 'confirmation' | 'admin-login' | 'admin-panel';
const configuredApiBase = process.env.REACT_APP_API_BASE_URL;
const API_BASES = configuredApiBase
  ? [configuredApiBase]
  : ['http://localhost:5000/api', 'http://localhost:3100/api'];
const ADMIN_USERNAME = process.env.REACT_APP_ADMIN_USERNAME || 'admin';
const ADMIN_PASSWORD = process.env.REACT_APP_ADMIN_PASSWORD || 'admin123';

const parseJsonSafe = async (response: Response) => {
  try {
    return await response.json();
  } catch {
    return null;
  }
};

const apiFetch = async (path: string, options?: RequestInit) => {
  let networkError: any = null;

  for (const baseUrl of API_BASES) {
    try {
      const response = await fetch(`${baseUrl}${path}`, options);
      return response;
    } catch (error: any) {
      networkError = error;
    }
  }

  throw new Error(networkError?.message || 'Unable to connect to API server');
};

interface BookingData {
  name: string;
  mobile: string;
  checkinDate: string;
  checkoutDate: string;
  paymentAmount: number;
  paymentType: 'advance' | 'full' | 'custom';
  totalAmount: number;
  customAmount: number;
  whatsappNotification: boolean;
  profilePhoto: string | null;
}

interface BookingRecord {
  _id: string;
  name: string;
  mobile: string;
  checkinDate: string;
  checkoutDate: string;
  paymentAmount: number;
  paymentType: 'advance' | 'full' | 'custom';
  totalAmount: number;
  status: string;
  source: string;
  createdAt: string;
}

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('login');
  const [saveError, setSaveError] = useState<string>('');
  const [isAdminLoggedIn, setIsAdminLoggedIn] = useState<boolean>(() => {
    return window.sessionStorage.getItem('adminLoggedIn') === 'true';
  });
  const [bookingData, setBookingData] = useState<BookingData>({
    name: '',
    mobile: '',
    checkinDate: '',
    checkoutDate: '',
    paymentAmount: 1000,
    paymentType: 'advance',
    totalAmount: 3500,
    customAmount: 1000,
    whatsappNotification: true,
    profilePhoto: null
  });

  const saveBookingToMongo = async () => {
    setSaveError('');
    try {
      const response = await apiFetch('/bookings/public', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(bookingData)
      });

      const result = await parseJsonSafe(response);
      if (!response.ok) {
        throw new Error(result?.error || result?.message || 'Unable to save booking');
      }
    } catch (error: any) {
      setSaveError(error?.message || 'Unable to save booking');
    } finally {
      setCurrentPage('confirmation');
    }
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'login':
        return <LoginPage 
          bookingData={bookingData}
          setBookingData={setBookingData}
          onNext={() => setCurrentPage('booking')} 
          onBack={() => setCurrentPage('login')} 
        />;
      case 'booking':
        return (
          <BookingPage 
            bookingData={bookingData}
            setBookingData={setBookingData}
            onNext={() => setCurrentPage('payment')}
            onBack={() => setCurrentPage('login')}
          />
        );
      case 'payment':
        return (
          <PaymentPage 
            amount={bookingData.paymentAmount}
            onSuccess={saveBookingToMongo}
            onBack={() => setCurrentPage('booking')}
          />
        );
      case 'confirmation':
        return <ConfirmationPage bookingData={bookingData} saveError={saveError} onNewBooking={() => {
          setCurrentPage('login');
          setSaveError('');
          setBookingData({ name: '', mobile: '', checkinDate: '', checkoutDate: '', paymentAmount: 1000, paymentType: 'advance', totalAmount: 3500, customAmount: 1000, whatsappNotification: true, profilePhoto: null });
        }} />;
      case 'admin-login':
        return (
          <AdminLoginPage
            onBack={() => setCurrentPage('login')}
            onLoginSuccess={() => {
              setIsAdminLoggedIn(true);
              window.sessionStorage.setItem('adminLoggedIn', 'true');
              setCurrentPage('admin-panel');
            }}
          />
        );
      case 'admin-panel':
        if (!isAdminLoggedIn) {
          return (
            <AdminLoginPage
              onBack={() => setCurrentPage('login')}
              onLoginSuccess={() => {
                setIsAdminLoggedIn(true);
                window.sessionStorage.setItem('adminLoggedIn', 'true');
                setCurrentPage('admin-panel');
              }}
            />
          );
        }
        return (
          <AdminPanelPage
            onBackToBooking={() => setCurrentPage('login')}
            onLogout={() => {
              setIsAdminLoggedIn(false);
              window.sessionStorage.removeItem('adminLoggedIn');
              setCurrentPage('login');
            }}
          />
        );
      default:
        return <LoginPage 
          bookingData={bookingData}
          setBookingData={setBookingData}
          onNext={() => setCurrentPage('booking')} 
          onBack={() => setCurrentPage('login')} 
        />;
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      fontFamily: 'Arial, sans-serif'
    }}>
      {renderPage()}
    </div>
  );
};

// Login/Register Page
const LoginPage: React.FC<{ 
  bookingData: BookingData;
  setBookingData: (data: BookingData) => void;
  onNext: () => void; 
  onBack: () => void;
}> = ({ bookingData, setBookingData, onNext, onBack }) => {

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validate name
    if (!bookingData.name.trim()) {
      alert('Please enter your full name');
      return;
    }

    // Validate mobile number
    if (!bookingData.mobile.trim()) {
      alert('Please enter your mobile number');
      return;
    }

    if (bookingData.mobile.length !== 10) {
      alert('Mobile number must be exactly 10 digits');
      return;
    }

    if (!/^[0-9]+$/.test(bookingData.mobile)) {
      alert('Mobile number should contain only numbers');
      return;
    }

    onNext();
  };

  // Function to capitalize each word
  const capitalizeWords = (str: string) => {
    return str.replace(/\b\w/g, (char) => char.toUpperCase());
  };

  // Function to handle name input with auto-capitalization
  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    // Only allow letters and spaces
    const filteredValue = value.replace(/[^a-zA-Z\s]/g, '');
    // Capitalize first letter of each word
    const capitalizedValue = capitalizeWords(filteredValue);
    setBookingData({ ...bookingData, name: capitalizedValue });
  };

  // Function to handle mobile input with digit restriction
  const handleMobileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    // Only allow numbers and limit to 10 digits
    const filteredValue = value.replace(/[^0-9]/g, '').slice(0, 10);
    setBookingData({ ...bookingData, mobile: filteredValue });
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Check file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        alert('Photo size should be less than 5MB');
        return;
      }

      // Check file type
      if (!file.type.startsWith('image/')) {
        alert('Please select a valid image file');
        return;
      }

      const reader = new FileReader();
      reader.onload = (event) => {
        setBookingData({ ...bookingData, profilePhoto: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const removePhoto = () => {
    setBookingData({ ...bookingData, profilePhoto: null });
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        borderRadius: '20px',
        padding: '40px',
        maxWidth: '450px',
        width: '100%',
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)'
      }}>
        <button
          onClick={onBack}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.5rem',
            cursor: 'pointer',
            marginBottom: '20px',
            color: '#667eea'
          }}
        >
          ← Back
        </button>

        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <div style={{ position: 'relative', display: 'inline-block', marginBottom: '15px' }}>
            {bookingData.profilePhoto ? (
              <div style={{ position: 'relative' }}>
                <img 
                  src={bookingData.profilePhoto} 
                  alt="Profile" 
                  style={{
                    width: '80px',
                    height: '80px',
                    borderRadius: '50%',
                    objectFit: 'cover',
                    border: '3px solid #667eea',
                    boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
                  }}
                />
                <button
                  onClick={removePhoto}
                  style={{
                    position: 'absolute',
                    top: '-5px',
                    right: '-5px',
                    background: '#ff4757',
                    color: 'white',
                    border: 'none',
                    borderRadius: '50%',
                    width: '24px',
                    height: '24px',
                    cursor: 'pointer',
                    fontSize: '12px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                  }}
                >
                  ×
                </button>
              </div>
            ) : (
              <div style={{ fontSize: '3rem', marginBottom: '0' }}>👤</div>
            )}

            <div style={{ marginTop: '10px' }}>
              <label style={{
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: 'white',
                padding: '8px 16px',
                borderRadius: '20px',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: '500',
                display: 'inline-block',
                transition: 'transform 0.2s ease'
              }}>
                📷 {bookingData.profilePhoto ? 'Change Photo' : 'Add Photo'}
                <input
                  type="file"
                  accept="image/*"
                  onChange={handlePhotoUpload}
                  style={{ display: 'none' }}
                />
              </label>
            </div>
          </div>

          <h2 style={{ color: '#333', margin: '0 0 10px 0', fontSize: '2rem', fontWeight: '300' }}>
            Customer Details
          </h2>
          <p style={{ color: '#666', margin: 0 }}>Enter your information to continue</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              👤 Full Name
            </label>
            <input
              type="text"
              value={bookingData.name}
              onChange={handleNameChange}
              placeholder="Enter your full name"
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                transition: 'border-color 0.3s ease',
                boxSizing: 'border-box'
              }}
              onFocus={(e) => e.target.style.borderColor = '#667eea'}
              onBlur={(e) => e.target.style.borderColor = '#e1e8ed'}
              required
            />
            <div style={{ fontSize: '0.8rem', color: '#666', marginTop: '5px' }}>
              Only letters and spaces allowed. First letter of each word will be capitalized.
            </div>
          </div>

          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              📱 Mobile Number
            </label>
            <input
              type="tel"
              value={bookingData.mobile}
              onChange={handleMobileChange}
              placeholder="Enter your 10-digit mobile number"
              maxLength={10}
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                transition: 'border-color 0.3s ease',
                boxSizing: 'border-box'
              }}
              onFocus={(e) => e.target.style.borderColor = '#667eea'}
              onBlur={(e) => e.target.style.borderColor = '#e1e8ed'}
              required
            />
            <div style={{ fontSize: '0.8rem', color: '#666', marginTop: '5px' }}>
              {bookingData.mobile.length}/10 digits entered. Only numbers allowed.
            </div>
          </div>

          <div style={{ marginBottom: '30px' }}>
            <label style={{
              display: 'flex',
              alignItems: 'center',
              cursor: 'pointer',
              padding: '15px',
              border: '2px solid #e1e8ed',
              borderRadius: '10px',
              transition: 'border-color 0.3s ease',
              background: bookingData.whatsappNotification ? '#f0f8ff' : 'transparent'
            }}>
              <input
                type="checkbox"
                checked={bookingData.whatsappNotification}
                onChange={(e) => setBookingData({ ...bookingData, whatsappNotification: e.target.checked })}
                style={{
                  marginRight: '12px',
                  transform: 'scale(1.2)'
                }}
              />
              <div>
                <div style={{ fontWeight: '600', color: '#333', marginBottom: '4px' }}>
                  📲 WhatsApp Notifications
                </div>
                <div style={{ fontSize: '0.9rem', color: '#666' }}>
                  Get instant booking confirmation and updates on WhatsApp
                </div>
              </div>
            </label>
          </div>

          <button
            type="submit"
            style={{
              width: '100%',
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '15px',
              padding: '18px',
              fontSize: '1.1rem',
              fontWeight: '600',
              cursor: 'pointer',
              transition: 'transform 0.2s ease',
              boxShadow: '0 5px 15px rgba(102, 126, 234, 0.3)'
            }}
            onMouseOver={(e) => e.currentTarget.style.transform = 'translateY(-2px)'}
            onMouseOut={(e) => e.currentTarget.style.transform = 'translateY(0)'}
          >
            Continue to Booking →
          </button>
        </form>
      </div>
    </div>
  );
};

// Booking Page
const BookingPage: React.FC<{
  bookingData: BookingData;
  setBookingData: (data: BookingData) => void;
  onNext: () => void;
  onBack: () => void;
}> = ({ bookingData, setBookingData, onNext, onBack }) => {
  const [bookedDates, setBookedDates] = useState<string[]>([]);
  const [bookedByDate, setBookedByDate] = useState<Record<string, string[]>>({});
  const [bookingAvailabilityError, setBookingAvailabilityError] = useState('');
  const [calendarMonth, setCalendarMonth] = useState<Date>(() => {
    const now = new Date();
    return new Date(now.getFullYear(), now.getMonth(), 1);
  });

  // Calculate total amount based on dates
  const calculateTotalAmount = (checkinDate: string, checkoutDate: string) => {
    if (!checkinDate || !checkoutDate) return 3500; // Default amount

    const checkin = new Date(checkinDate);
    const checkout = new Date(checkoutDate);
    const diffTime = Math.abs(checkout.getTime() - checkin.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    // Base rate: ₹3500 per day
    const baseRate = 3500;
    const totalAmount = Math.max(diffDays * baseRate, 3500); // Minimum ₹3500

    return totalAmount;
  };

  // Calculate minimum advance payment
  const calculateMinAdvance = (totalAmount: number, days: number) => {
    if (days <= 1) {
      return 1000; // Single day minimum ₹1000
    } else {
      return Math.ceil(totalAmount * 0.3); // 30% for multiple days
    }
  };

  // Update total amount when dates change
  React.useEffect(() => {
    if (bookingData.checkinDate && bookingData.checkoutDate) {
      const checkin = new Date(bookingData.checkinDate);
      const checkout = new Date(bookingData.checkoutDate);
      const days = Math.ceil(Math.abs(checkout.getTime() - checkin.getTime()) / (1000 * 60 * 60 * 24));
      const newTotalAmount = calculateTotalAmount(bookingData.checkinDate, bookingData.checkoutDate);
      const minAdvance = calculateMinAdvance(newTotalAmount, days);

      setBookingData({ 
        ...bookingData, 
        totalAmount: newTotalAmount,
        // Reset payment amount if it exceeds new total or below minimum
        paymentAmount: bookingData.paymentType === 'full' ? newTotalAmount : 
                      bookingData.paymentType === 'advance' ? minAdvance :
                      bookingData.paymentType === 'custom' && (bookingData.paymentAmount > newTotalAmount || bookingData.paymentAmount < minAdvance) ? minAdvance : bookingData.paymentAmount,
        customAmount: Math.max(minAdvance, Math.min(bookingData.customAmount, newTotalAmount))
      });
    }
  }, [bookingData.checkinDate, bookingData.checkoutDate]);

  const isDateBooked = (date: string) => bookedDates.includes(date);
  const getBookedByText = (date: string) => {
    const names = bookedByDate[date] || [];
    if (!names.length) return '';
    return names.join(', ');
  };

  const getDateKey = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getRangeDates = (startDate: string, endDate: string) => {
    const dates: string[] = [];
    const current = new Date(startDate);
    const end = new Date(endDate);

    while (current < end) {
      dates.push(current.toISOString().split('T')[0]);
      current.setDate(current.getDate() + 1);
    }

    return dates;
  };

  React.useEffect(() => {
    const loadBookedDates = async () => {
      setBookingAvailabilityError('');
      try {
        const response = await apiFetch('/bookings');
        const result = await parseJsonSafe(response);
        if (!response.ok) {
          throw new Error(result?.error || result?.message || 'Unable to load booked dates');
        }

        const reserved = new Set<string>();
        const bookedNameMap: Record<string, string[]> = {};
        const addBookedName = (date: string, name: string) => {
          if (!bookedNameMap[date]) bookedNameMap[date] = [];
          if (!bookedNameMap[date].includes(name)) {
            bookedNameMap[date].push(name);
          }
        };
        (result.bookings || []).forEach((booking: any) => {
          if (booking?.status === 'canceled') return;
          const bookerName = (booking?.name || 'Unknown').trim();
          const checkin = booking?.checkinDate ? new Date(booking.checkinDate) : null;
          const checkout = booking?.checkoutDate ? new Date(booking.checkoutDate) : null;

          if (checkin && checkout && !Number.isNaN(checkin.getTime()) && !Number.isNaN(checkout.getTime()) && checkout > checkin) {
            const cursor = new Date(checkin);
            while (cursor < checkout) {
              const bookedDate = cursor.toISOString().split('T')[0];
              reserved.add(bookedDate);
              addBookedName(bookedDate, bookerName);
              cursor.setDate(cursor.getDate() + 1);
            }
            return;
          }

          if (booking?.bookingDate) {
            const singleDate = new Date(booking.bookingDate);
            if (!Number.isNaN(singleDate.getTime())) {
              const bookedDate = singleDate.toISOString().split('T')[0];
              reserved.add(bookedDate);
              addBookedName(bookedDate, bookerName);
            }
          }
        });

        setBookedDates(Array.from(reserved));
        setBookedByDate(bookedNameMap);
      } catch (error: any) {
        setBookingAvailabilityError(error?.message || 'Unable to load booked dates');
      }
    };

    loadBookedDates();
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (bookingData.checkinDate && bookingData.checkoutDate) {
      if (new Date(bookingData.checkinDate) >= new Date(bookingData.checkoutDate)) {
        alert('Check-out date must be after check-in date');
        return;
      }

      const selectedRangeDates = getRangeDates(bookingData.checkinDate, bookingData.checkoutDate);
      const hasBookedDate = selectedRangeDates.some((date) => isDateBooked(date));
      if (hasBookedDate) {
        alert('Selected date is already booked. Please choose another date.');
        return;
      }
      onNext();
    } else {
      alert('Please select both check-in and check-out dates');
    }
  };

  // Generate available dates (next 120 days to cover through March)
  const getAvailableDates = () => {
    const dates = [];
    const today = new Date();
    for (let i = 0; i < 120; i++) {
      const date = new Date(today);
      date.setDate(today.getDate() + i);
      dates.push(date.toISOString().split('T')[0]);
    }
    return dates;
  };

  const availableDates = getAvailableDates();

  const renderCalendar = () => {
    const year = calendarMonth.getFullYear();
    const month = calendarMonth.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startWeekDay = firstDay.getDay();
    const totalDays = lastDay.getDate();
    const cells: React.ReactNode[] = [];

    for (let i = 0; i < startWeekDay; i++) {
      cells.push(<div key={`blank-${i}`} />);
    }

    for (let day = 1; day <= totalDays; day++) {
      const date = new Date(year, month, day);
      const dateKey = getDateKey(date);
      const isBooked = isDateBooked(dateKey);
      const bookerNames = getBookedByText(dateKey);

      cells.push(
        <div
          key={dateKey}
          style={{
            minHeight: '84px',
            border: '1px solid #e9ecef',
            borderRadius: '8px',
            padding: '6px',
            background: isBooked ? '#fff5f5' : '#f8f9fa'
          }}
        >
          <div style={{ fontWeight: 700, fontSize: '0.85rem', marginBottom: '4px', color: '#333' }}>{day}</div>
          {isBooked ? (
            <div style={{ fontSize: '0.72rem', color: '#c92a2a', lineHeight: 1.3 }}>
              {bookerNames}
            </div>
          ) : (
            <div style={{ fontSize: '0.72rem', color: '#868e96' }}>Available</div>
          )}
        </div>
      );
    }

    return cells;
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
