        background: 'rgba(255, 255, 255, 0.95)',
        borderRadius: '20px',
        padding: '40px',
        maxWidth: '500px',
        width: '100%',
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)'
      }}>
        <button
          onClick={onBack}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.5rem',
            cursor: 'pointer',
            marginBottom: '20px',
            color: '#667eea'
          }}
        >
          ← Back
        </button>

        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <div style={{ fontSize: '3rem', marginBottom: '15px' }}>📅</div>
          <h2 style={{ color: '#333', margin: '0 0 10px 0', fontSize: '2rem', fontWeight: '300' }}>
            Booking Details
          </h2>
          <p style={{ color: '#666', margin: 0 }}>Select your check-in and check-out dates</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              📅 Check-in Date
            </label>
            <select
              value={bookingData.checkinDate}
              onChange={(e) => {
                const newCheckinDate = e.target.value;
                if (isDateBooked(newCheckinDate)) {
                  alert('Selected check-in date is already booked');
                  return;
                }
                const newData = { ...bookingData, checkinDate: newCheckinDate };

                // Clear checkout date if it's invalid (same or before new checkin date)
                if (bookingData.checkoutDate && bookingData.checkoutDate <= newCheckinDate) {
                  newData.checkoutDate = '';
                }

                setBookingData(newData);
              }}
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                boxSizing: 'border-box',
                background: 'white'
              }}
              required
            >
              <option value="">Select check-in date</option>
              {availableDates.map(date => (
                <option key={date} value={date} disabled={isDateBooked(date)}>
                  {new Date(date).toLocaleDateString('en-US', { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}{isDateBooked(date) ? ` (Already Booked by ${getBookedByText(date) || 'Unknown'})` : ''}
                </option>
              ))}
            </select>
            {bookingData.checkinDate && isDateBooked(bookingData.checkinDate) && (
              <div style={{ fontSize: '0.8rem', color: '#dc3545', marginTop: '5px' }}>
                This date is already booked by {getBookedByText(bookingData.checkinDate) || 'someone'}.
              </div>
            )}
            {bookingAvailabilityError && (
              <div style={{ fontSize: '0.8rem', color: '#dc3545', marginTop: '5px' }}>
