              <div style={{ textAlign: 'center' }}>Fri</div>
              <div style={{ textAlign: 'center' }}>Sat</div>
            </div>

            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(7, minmax(0, 1fr))',
              gap: '6px'
            }}>
