const BookingRecordsPanel: React.FC = () => {
  const [records, setRecords] = useState<BookingRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const loadRecords = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await apiFetch('/bookings');
      const result = await parseJsonSafe(response);
      if (!response.ok) {
        throw new Error(result?.error || result?.message || 'Unable to load records');
      }
      setRecords(result.bookings || []);
    } catch (err: any) {
      setError(err?.message || 'Unable to load records');
    } finally {
      setLoading(false);
    }
  };

  React.useEffect(() => {
    loadRecords();
  }, []);

  const exportExcel = async () => {
    setError('');
    try {
      const response = await apiFetch('/bookings/export');
      if (!response.ok) {
        throw new Error('Export failed');
      }
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `bookings-${new Date().toISOString().split('T')[0]}.xlsx`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err: any) {
      setError(err?.message || 'Export failed');
    }
  };

  const importExcel = async (file: File) => {
    setError('');
    try {
      const formData = new FormData();
      formData.append('file', file);

      const response = await apiFetch('/bookings/import', {
        method: 'POST',
        body: formData
      });
      const result = await parseJsonSafe(response);
      if (!response.ok) {
        throw new Error(result?.error || result?.message || 'Import failed');
      }
      await loadRecords();
      alert(`Import success. ${result.importedCount || 0} record(s) added.`);
    } catch (err: any) {
      setError(err?.message || 'Import failed');
    }
  };

  return (
    <div style={{
      marginTop: '30px',
      textAlign: 'left',
      borderTop: '1px solid #e9ecef',
      paddingTop: '20px'
    }}>
      <h3 style={{ margin: '0 0 12px 0', color: '#333', textAlign: 'center' }}>Booking Records (MongoDB + Excel)</h3>
      <div style={{ display: 'flex', gap: '10px', justifyContent: 'center', flexWrap: 'wrap', marginBottom: '14px' }}>
        <button
          onClick={loadRecords}
          style={{
            background: '#1e88e5',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            padding: '10px 14px',
            cursor: 'pointer'
          }}
        >
          Refresh
        </button>
        <button
          onClick={exportExcel}
          style={{
            background: '#2e7d32',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            padding: '10px 14px',
            cursor: 'pointer'
          }}
        >
          Export Excel
        </button>
        <label style={{
          background: '#6a1b9a',
          color: 'white',
          borderRadius: '8px',
          padding: '10px 14px',
          cursor: 'pointer'
        }}>
          Import Excel
          <input
            type="file"
            accept=".xlsx,.xls"
            style={{ display: 'none' }}
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) {
                importExcel(file);
                e.currentTarget.value = '';
              }
            }}
          />
        </label>
      </div>

      {loading && <div style={{ color: '#666', textAlign: 'center', marginBottom: '10px' }}>Loading records...</div>}
      {error && <div style={{ color: '#dc3545', textAlign: 'center', marginBottom: '10px' }}>{error}</div>}

      <div style={{ maxHeight: '230px', overflow: 'auto', border: '1px solid #e9ecef', borderRadius: '10px' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.88rem' }}>
          <thead style={{ background: '#f8f9fa' }}>
            <tr>
              <th style={{ padding: '8px', borderBottom: '1px solid #e9ecef' }}>Name</th>
              <th style={{ padding: '8px', borderBottom: '1px solid #e9ecef' }}>Mobile</th>
              <th style={{ padding: '8px', borderBottom: '1px solid #e9ecef' }}>Check-in</th>
              <th style={{ padding: '8px', borderBottom: '1px solid #e9ecef' }}>Paid</th>
              <th style={{ padding: '8px', borderBottom: '1px solid #e9ecef' }}>Source</th>
            </tr>
          </thead>
          <tbody>
            {records.length === 0 && !loading ? (
              <tr>
                <td colSpan={5} style={{ textAlign: 'center', padding: '12px', color: '#666' }}>
                  No booking records found
                </td>
              </tr>
            ) : (
              records.map((record) => (
                <tr key={record._id}>
                  <td style={{ padding: '8px', borderBottom: '1px solid #f1f3f5' }}>{record.name}</td>
                  <td style={{ padding: '8px', borderBottom: '1px solid #f1f3f5' }}>{record.mobile}</td>
                  <td style={{ padding: '8px', borderBottom: '1px solid #f1f3f5' }}>
                    {new Date(record.checkinDate).toLocaleDateString('en-IN')}
                  </td>
                  <td style={{ padding: '8px', borderBottom: '1px solid #f1f3f5' }}>Rs {record.paymentAmount}</td>
                  <td style={{ padding: '8px', borderBottom: '1px solid #f1f3f5' }}>{record.source}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

