const AdminPanelPage: React.FC<{ onBackToBooking: () => void; onLogout: () => void }> = ({ onBackToBooking, onLogout }) => {
  const [records, setRecords] = useState<BookingRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [calendarMonth, setCalendarMonth] = useState<Date>(() => {
    const now = new Date();
    return new Date(now.getFullYear(), now.getMonth(), 1);
  });

  const loadRecords = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await apiFetch('/bookings');
      const result = await parseJsonSafe(response);
      if (!response.ok) {
        throw new Error(result?.error || result?.message || 'Unable to load bookings');
      }
      setRecords(result.bookings || []);
    } catch (err: any) {
      setError(err?.message || 'Unable to load bookings');
    } finally {
      setLoading(false);
    }
  };

  React.useEffect(() => {
    loadRecords();
  }, []);

  const bookedByDate: Record<string, string[]> = {};
  records.forEach((record) => {
    if (record.status === 'canceled') return;
    const checkin = new Date(record.checkinDate);
    const checkout = new Date(record.checkoutDate);
    const cursor = new Date(checkin);
    while (cursor < checkout) {
      const dateKey = cursor.toISOString().split('T')[0];
      if (!bookedByDate[dateKey]) {
        bookedByDate[dateKey] = [];
      }
      if (!bookedByDate[dateKey].includes(record.name)) {
        bookedByDate[dateKey].push(record.name);
      }
      cursor.setDate(cursor.getDate() + 1);
    }
  });

  const monthYearTitle = calendarMonth.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  const firstDay = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), 1);
  const lastDay = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 0);
  const prefix = firstDay.getDay();
  const totalDays = lastDay.getDate();

  const calendarCells: React.ReactNode[] = [];
  for (let i = 0; i < prefix; i++) {
    calendarCells.push(<div key={`blank-${i}`} />);
  }
  for (let day = 1; day <= totalDays; day++) {
    const date = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), day);
    const dateKey = date.toISOString().split('T')[0];
    const names = bookedByDate[dateKey] || [];
    calendarCells.push(
      <div
        key={dateKey}
        style={{
          minHeight: '96px',
          padding: '8px',
          borderRadius: '10px',
          border: names.length ? '1px solid #f59e0b' : '1px solid #cbd5e1',
          background: names.length ? 'linear-gradient(180deg, #fff7ed 0%, #ffedd5 100%)' : 'linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%)'
        }}
      >
        <div style={{ fontWeight: 700, color: '#0f172a', marginBottom: '4px' }}>{day}</div>
        {names.length ? (
          <div style={{ fontSize: '0.74rem', color: '#9a3412', lineHeight: 1.25 }}>{names.join(', ')}</div>
        ) : (
          <div style={{ fontSize: '0.72rem', color: '#64748b' }}>Open</div>
        )}
      </div>
    );
  }

  const confirmedCount = records.filter((r) => r.status === 'confirmed').length;

  return (
    <div style={{ minHeight: '100vh', padding: '20px' }}>
      <div style={{ maxWidth: '1180px', margin: '0 auto' }}>
        <div style={{
          background: 'linear-gradient(120deg, #0f172a 0%, #1d4ed8 45%, #0f766e 100%)',
          color: 'white',
          borderRadius: '20px',
          padding: '20px',
          marginBottom: '16px',
          boxShadow: '0 20px 40px rgba(15,23,42,0.25)'
        }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', gap: '10px', flexWrap: 'wrap' }}>
            <div>
              <h2 style={{ margin: 0 }}>Admin Booking Dashboard</h2>
              <p style={{ margin: '6px 0 0 0', opacity: 0.9 }}>Database synced calendar and booking details</p>
            </div>
            <div style={{ display: 'flex', gap: '8px' }}>
              <button onClick={onBackToBooking} style={{ border: 'none', borderRadius: '10px', padding: '10px 14px', cursor: 'pointer' }}>Booking Screen</button>
              <button onClick={onLogout} style={{ border: 'none', borderRadius: '10px', padding: '10px 14px', cursor: 'pointer' }}>Logout</button>
            </div>
          </div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(170px, 1fr))', gap: '12px', marginBottom: '16px' }}>
          <div style={{ background: '#0f766e', color: 'white', borderRadius: '14px', padding: '14px' }}>
            <div style={{ fontSize: '0.85rem', opacity: 0.9 }}>Total Bookings</div>
            <div style={{ fontSize: '1.8rem', fontWeight: 700 }}>{records.length}</div>
          </div>
          <div style={{ background: '#b45309', color: 'white', borderRadius: '14px', padding: '14px' }}>
            <div style={{ fontSize: '0.85rem', opacity: 0.9 }}>Confirmed</div>
            <div style={{ fontSize: '1.8rem', fontWeight: 700 }}>{confirmedCount}</div>
          </div>
          <div style={{ background: '#1d4ed8', color: 'white', borderRadius: '14px', padding: '14px' }}>
            <div style={{ fontSize: '0.85rem', opacity: 0.9 }}>Data Source</div>
            <div style={{ fontSize: '1.2rem', fontWeight: 700 }}>MongoDB</div>
          </div>
          <div style={{ background: '#7c3aed', color: 'white', borderRadius: '14px', padding: '14px' }}>
            <div style={{ fontSize: '0.85rem', opacity: 0.9 }}>Actions</div>
            <button onClick={loadRecords} style={{ marginTop: '6px', border: 'none', borderRadius: '8px', padding: '8px 12px', cursor: 'pointer' }}>Refresh</button>
          </div>
        </div>

        {error && <div style={{ color: '#b91c1c', marginBottom: '10px' }}>{error}</div>}
        {loading && <div style={{ color: '#334155', marginBottom: '10px' }}>Loading...</div>}

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '14px' }}>
          <div style={{ background: 'rgba(255,255,255,0.95)', borderRadius: '16px', padding: '14px', boxShadow: '0 12px 26px rgba(0,0,0,0.12)' }}>
            <h3 style={{ marginTop: 0, color: '#0f172a' }}>Booking Details</h3>
            <div style={{ maxHeight: '560px', overflow: 'auto', border: '1px solid #e2e8f0', borderRadius: '10px' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.85rem' }}>
                <thead style={{ background: '#f1f5f9' }}>
                  <tr>
                    <th style={{ textAlign: 'left', padding: '8px', borderBottom: '1px solid #e2e8f0' }}>Name</th>
                    <th style={{ textAlign: 'left', padding: '8px', borderBottom: '1px solid #e2e8f0' }}>Mobile</th>
                    <th style={{ textAlign: 'left', padding: '8px', borderBottom: '1px solid #e2e8f0' }}>Check-in</th>
                    <th style={{ textAlign: 'left', padding: '8px', borderBottom: '1px solid #e2e8f0' }}>Check-out</th>
                  </tr>
                </thead>
                <tbody>
                  {!records.length ? (
                    <tr>
                      <td colSpan={4} style={{ padding: '10px', color: '#64748b' }}>No records</td>
                    </tr>
                  ) : (
                    records.map((row) => (
                      <tr key={row._id}>
                        <td style={{ padding: '8px', borderBottom: '1px solid #f1f5f9' }}>{row.name}</td>
                        <td style={{ padding: '8px', borderBottom: '1px solid #f1f5f9' }}>{row.mobile}</td>
                        <td style={{ padding: '8px', borderBottom: '1px solid #f1f5f9' }}>{new Date(row.checkinDate).toLocaleDateString('en-IN')}</td>
                        <td style={{ padding: '8px', borderBottom: '1px solid #f1f5f9' }}>{new Date(row.checkoutDate).toLocaleDateString('en-IN')}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>

          <div style={{ background: 'rgba(255,255,255,0.95)', borderRadius: '16px', padding: '14px', boxShadow: '0 12px 26px rgba(0,0,0,0.12)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px', alignItems: 'center' }}>
              <button onClick={() => setCalendarMonth(new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() - 1, 1))} style={{ border: '1px solid #cbd5e1', borderRadius: '8px', padding: '6px 10px', background: 'white', cursor: 'pointer' }}>Prev</button>
              <h3 style={{ margin: 0, color: '#0f172a' }}>{monthYearTitle}</h3>
              <button onClick={() => setCalendarMonth(new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 1))} style={{ border: '1px solid #cbd5e1', borderRadius: '8px', padding: '6px 10px', background: 'white', cursor: 'pointer' }}>Next</button>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, minmax(0, 1fr))', gap: '6px', marginBottom: '8px', fontWeight: 700, color: '#334155', fontSize: '0.77rem' }}>
              <div style={{ textAlign: 'center' }}>Sun</div>
              <div style={{ textAlign: 'center' }}>Mon</div>
              <div style={{ textAlign: 'center' }}>Tue</div>
              <div style={{ textAlign: 'center' }}>Wed</div>
              <div style={{ textAlign: 'center' }}>Thu</div>
              <div style={{ textAlign: 'center' }}>Fri</div>
              <div style={{ textAlign: 'center' }}>Sat</div>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, minmax(0, 1fr))', gap: '6px' }}>
              {calendarCells}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// Add CSS animations
const style = document.createElement('style');
style.textContent = `
  @keyframes pulse {
    0% { opacity: 1; }
    50% { opacity: 0.5; }
    100% { opacity: 1; }
  }
  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
`;
document.head.appendChild(style);
export default App;
